<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title><?= htmlspecialchars($title) ?></title><style>:root{--doc-primary:<?= htmlspecialchars($brand['primary']??'#123f3a') ?>;--doc-accent:<?= htmlspecialchars($brand['accent']??'#d89b2b') ?>}*{box-sizing:border-box}body{margin:0;background:#e9efec;font-family:Arial,sans-serif;color:#173b35}.document-tools{text-align:center;padding:18px}.document-tools button,.document-tools a{display:inline-flex;border:0;border-radius:8px;background:var(--doc-primary);color:#fff;padding:12px 18px;text-decoration:none;margin:4px;font-weight:700;cursor:pointer}.official-document{width:1120px;height:790px;margin:0 auto 35px;background:#fff;padding:50px 60px;position:relative;overflow:hidden;box-shadow:0 25px 60px #123f3a22}.document-frame{position:absolute;inset:18px;border:3px solid var(--doc-primary);outline:1px solid var(--doc-accent);outline-offset:-10px;pointer-events:none}.official-document:before,.official-document:after{content:'';position:absolute;width:260px;height:260px;border-radius:50%;border:60px solid color-mix(in srgb,var(--doc-accent) 12%,transparent)}.official-document:before{left:-160px;top:-170px}.official-document:after{right:-170px;bottom:-180px}.official-document header{display:flex;align-items:center;justify-content:space-between;position:relative;z-index:1}.document-brand{display:flex;align-items:center;gap:12px}.document-brand>span{width:56px;height:56px;border-radius:16px;display:grid;place-items:center;background:var(--doc-primary);color:#fff;font-size:20px;font-weight:800}.document-brand img{max-width:120px;max-height:62px}.document-brand div{display:flex;flex-direction:column}.document-brand strong{font-size:22px}.document-brand small{font-size:8px;letter-spacing:1.5px;color:#73837e}.document-reference{font-size:9px;color:#697a75}.document-title{text-align:center;margin-top:55px}.document-title p{font-size:9px;letter-spacing:4px;color:var(--doc-accent);font-weight:800}.document-title h1{font:800 43px Georgia,serif;letter-spacing:2px;margin:12px 0}.document-title i{display:block;width:85px;height:3px;margin:auto;background:var(--doc-accent)}.document-recipient{text-align:center;margin-top:27px}.document-recipient p{color:#697873;margin:8px}.document-recipient h2{font:italic 700 34px Georgia,serif;margin:8px;display:inline-block;border-bottom:1px solid var(--doc-accent);padding:0 30px 7px}.document-recipient h3{font:700 21px Georgia,serif;margin:13px auto;max-width:760px}.document-meta{display:flex;justify-content:center;gap:70px;margin:34px 0}.document-meta div{display:flex;flex-direction:column;text-align:center}.document-meta small{font-size:7px;letter-spacing:1.2px;color:#7b8985}.document-meta strong{font-size:12px;margin-top:5px}.official-document footer{display:flex;align-items:flex-end;justify-content:space-between;padding:0 45px}.signature{display:flex;flex-direction:column;text-align:center}.signature i{width:190px;border-top:1px solid #788680;margin-bottom:7px}.signature small{font-size:8px;color:#798681}.document-verification{display:flex;align-items:center;gap:10px;text-align:left}.document-verification img{width:76px;height:76px}.document-verification div{display:flex;flex-direction:column}.document-verification strong{font-size:9px}.document-verification small{font-size:7px;color:#78847f}.document-verification code{font-size:9px;margin-top:5px}.document-bottom{position:absolute;bottom:30px;left:60px;right:60px;text-align:center;font-size:6px;color:#82908b}@page{size:A4 landscape;margin:0}@media print{body{background:#fff}.document-tools{display:none}.official-document{width:297mm;height:210mm;margin:0;box-shadow:none;print-color-adjust:exact;-webkit-print-color-adjust:exact}}@media(max-width:1150px){.official-document{transform-origin:top left;transform:scale(.75);margin-bottom:-160px}}@media(max-width:850px){.official-document{transform:scale(.48);margin-bottom:-385px}}</style></head><body><?= $content ?></body></html>
